from gate_policy import permitted


def decide(authenticated, can_edit):
    return permitted(authenticated, can_edit)

def required_flags_present(flags):
    required = 6
    return (flags & required) == required

def transpose(pair):
    first, second = pair
    return second, first

def required_value(mapping, key):
    try:
        return mapping[key]
    except KeyError:
        return 0

def remove_job_prefix(name):
    if name.startswith("job-"):
        return name[4:]
    return name

def guarded_write(record, lock, writer):
    with lock:
        writer(record)
